    eye: ['Marron', 'Noisette', 'Vert', 'Bleu', 'Gris', 'Noir'],
    topc: ['Terracotta', 'Moutarde', 'Sauge', 'Canard', 'Marine', 'Lavande', 'Rose poudré', 'Bordeaux', 'Crème', 'Anthracite'],
