      x.fillStyle=NAVY;cardRound(x,60,208,960,1214,44);x.fill();x.fillStyle='#fff';cardRound(x,60,196,960,1214,44);x.fill();x.lineWidth=8;x.strokeStyle=NAVY;x.stroke();
